using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace Plagx.Preflight.Tests;

/// <summary>
/// parity/expected.json is generated by the JavaScript reference (plagx-preflight, npm run parity).
/// Every case must match exactly.
/// </summary>
public class ParityTests
{
    private static readonly JsonObject Data = JsonNode.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "parity", "expected.json")))!.AsObject();

    private static readonly JsonSerializerOptions Json = new() { WriteIndented = true, Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

    public static IEnumerable<object[]> Cases() =>
        Data["cases"]!.AsArray().Select((c, i) => new object[] { i, $"{c!["fixture"]} / {c["options"]}" });

    private static PreflightOptions Options(JsonObject o) => new()
    {
        MinWords = (int?)o["minWords"],
        MaxWords = (int?)o["maxWords"],
        Style = (string?)o["style"] ?? "apa",
        Checks = o["checks"]?.AsArray().Select(x => (string)x!).ToList(),
        RequiredHeadings = o["requiredHeadings"]?.AsArray().Select(x => (string)x!).ToList() ?? new List<string>(),
    };

    [Theory]
    [MemberData(nameof(Cases))]
    public void MatchesJavaScript(int index, string name)
    {
        var c = Data["cases"]![index]!;
        var text = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "fixtures", (string)c["fixture"]!), new System.Text.UTF8Encoding(false));
        var result = Preflight.CheckDraft(text, Options(Data["optionSets"]![(string)c["options"]!]!.AsObject()));
        var expected = c["result"]!.ToJsonString(Json);
        var actual = JsonSerializer.Serialize(result, Json);
        Assert.True(expected == actual, $"{name}\nexpected:\n{expected}\nactual:\n{actual}");
    }

    [Fact]
    public void CoversEveryFixture()
    {
        Assert.Equal(160, Data["cases"]!.AsArray().Count);
        Assert.Equal(Preflight.Version, (string)Data["version"]!);
    }
}
